 13→class TimelineItemProvider: TimelineItemProviderProtocol {
 14→    private var cancellables = Set<AnyCancellable>()
 15→    private let serialDispatchQueue: DispatchQueue
 16→    
 17→    private var roomTimelineObservationToken: TaskHandle?
 18→
 19→    private let paginationStateSubject = CurrentValueSubject<PaginationState, Never>(.initial)
 20→    var paginationState: PaginationState {
 21→        paginationStateSubject.value
 22→    }
 23→
 24→    private let itemProxiesSubject: CurrentValueSubject<[TimelineItemProxy], Never>
 25→    private(set) var itemProxies: [TimelineItemProxy] = [] {
 26→        didSet {
 27→            itemProxiesSubject.send(itemProxies)
 28→        }
 29→    }
 30→
 31→    var updatePublisher: AnyPublisher<([TimelineItemProxy], PaginationState), Never> {
 32→        itemProxiesSubject
 33→            .combineLatest(paginationStateSubject)
 34→            .eraseToAnyPublisher()
 35→    }
 36→    
 37→    let kind: TimelineKind
 38→    
 39→    private let membershipChangeSubject = PassthroughSubject<Void, Never>()
 40→    var membershipChangePublisher: AnyPublisher<Void, Never> {
 41→        membershipChangeSubject
 42→            .eraseToAnyPublisher()
 43→    }
 44→    
 45→    deinit {
 46→        roomTimelineObservationToken?.cancel()
 47→    }
 48→
 49→    init(timeline: Timeline, kind: TimelineKind, paginationStatePublisher: AnyPublisher<PaginationState, Never>) {
 50→        serialDispatchQueue = DispatchQueue(label: "io.element.elementx.timeline_item_provider", qos: .utility)
 51→        itemProxiesSubject = CurrentValueSubject<[TimelineItemProxy], Never>([])
 52→        self.kind = kind
 53→        
 54→        paginationStatePublisher
 55→            .sink { [weak self] in
 56→                self?.paginationStateSubject.send($0)
 57→            }
 58→            .store(in: &cancellables)
 59→        
 60→        Task {
 61→            roomTimelineObservationToken = await timeline.addListener(listener: SDKListener { [weak self] timelineDiffs in
 62→                self?.serialDispatchQueue.sync {
 63→                    self?.updateItemsWithDiffs(timelineDiffs)
 64→                }
 65→            })
 66→        }
 67→    }
 68→    
 69→    /// A continuation to signal whether the initial timeline items have been loaded and processed.
 70→    private var hasLoadedInitialItemsContinuation: CheckedContinuation<Void, Never>?
 71→    /// A method that allows `await`ing the first update of timeline items from the listener, as the items
 72→    /// aren't added directly to the provider upon initialisation and may take some time to come in.
 73→    func waitForInitialItems() async {
 74→        guard itemProxies.isEmpty else { return }
 75→        return await withCheckedContinuation { continuation in
 76→            hasLoadedInitialItemsContinuation = continuation
 77→        }
 78→    }
 79→    
 80→    // MARK: - Private
 81→    
 82→    private func updateItemsWithDiffs(_ diffs: [TimelineDiff]) {
 83→        let span = MXLog.createSpan("process_timeline_list_diffs:\(kind)")
 84→        span.enter()
 85→        defer {
 86→            span.exit()
 87→        }
 88→        
 89→        MXLog.verbose("Received diffs: \(diffs)")
 90→        
 91→        itemProxies = diffs.reduce(itemProxies) { currentItems, diff in
 92→            guard let collectionDiff = buildDiff(from: diff, on: currentItems) else {
 93→                MXLog.error("Failed building CollectionDifference from \(diff)")
 94→                return currentItems
 95→            }
 96→            
 97→            guard let updatedItems = currentItems.applying(collectionDiff) else {
 98→                MXLog.error("Failed applying diff: \(collectionDiff)")
 99→                return currentItems
100→            }
101→            
102→            return updatedItems
103→        }
104→        
105→        if let hasLoadedInitialItemsContinuation {
106→            hasLoadedInitialItemsContinuation.resume()
107→            self.hasLoadedInitialItemsContinuation = nil
108→        }
109→    }
110→    
111→    private func buildDiff(from diff: TimelineDiff, on itemProxies: [TimelineItemProxy]) -> CollectionDifference<TimelineItemProxy>? {
112→        var changes = [CollectionDifference<TimelineItemProxy>.Change]()
113→        
114→        switch diff {
115→        case .append(let items):
116→            for (index, item) in items.enumerated() {
117→                let itemProxy = TimelineItemProxy(item: item)
118→                
119→                if itemProxy.isMembershipChange {
120→                    membershipChangeSubject.send(())
121→                }
122→                
123→                changes.append(.insert(offset: Int(itemProxies.count) + index, element: itemProxy, associatedWith: nil))
124→            }
125→        case .clear:
126→            for (index, itemProxy) in itemProxies.enumerated() {
127→                changes.append(.remove(offset: index, element: itemProxy, associatedWith: nil))
128→            }
129→        case .insert(let index, let item):
130→            let itemProxy = TimelineItemProxy(item: item)
131→            changes.append(.insert(offset: Int(index), element: itemProxy, associatedWith: nil))
132→        case .popBack:
133→            guard let itemProxy = itemProxies.last else { fatalError() }
134→
135→            changes.append(.remove(offset: itemProxies.count - 1, element: itemProxy, associatedWith: nil))
136→        case .popFront:
137→            guard let itemProxy = itemProxies.first else { fatalError() }
138→
139→            changes.append(.remove(offset: 0, element: itemProxy, associatedWith: nil))
140→        case .pushBack(let item):
141→            let itemProxy = TimelineItemProxy(item: item)
142→            
143→            if itemProxy.isMembershipChange {
144→                membershipChangeSubject.send(())
145→            }
146→            
147→            changes.append(.insert(offset: Int(itemProxies.count), element: itemProxy, associatedWith: nil))
148→        case .pushFront(let item):
149→            let itemProxy = TimelineItemProxy(item: item)
150→            
151→            changes.append(.insert(offset: 0, element: itemProxy, associatedWith: nil))
152→        case .remove(let index):
153→            let itemProxy = itemProxies[Int(index)]
154→            
155→            changes.append(.remove(offset: Int(index), element: itemProxy, associatedWith: nil))
156→        case .reset(let items):
157→            for (index, itemProxy) in itemProxies.enumerated() {
158→                changes.append(.remove(offset: index, element: itemProxy, associatedWith: nil))
159→            }
160→
161→            for (index, timelineItem) in items.enumerated() {
162→                changes.append(.insert(offset: index, element: TimelineItemProxy(item: timelineItem), associatedWith: nil))
163→            }
164→        case .set(let index, let item):
165→            let itemProxy = TimelineItemProxy(item: item)
166→            changes.append(.remove(offset: Int(index), element: itemProxy, associatedWith: nil))
167→            changes.append(.insert(offset: Int(index), element: itemProxy, associatedWith: nil))
168→        case .truncate:
169→            break
170→        }
171→        
172→        return CollectionDifference(changes)
173→    }
174→}
